// Collapse all rows into one context string for the prompt.
const rows = $input.all().map(i => i.json);
const recent = rows.map(r => `- [${r.industry || 'general'}] ${r.title}`).join('\n');
return [{ json: { recent_context: recent || '(no recent posts)' } }];

