// Claude returns { content: [{ type: 'text', text: '[...]' }] }. Parse out the JSON array.
const raw = $input.first().json.content?.[0]?.text || '[]';
const cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
let ideas;
try { ideas = JSON.parse(cleaned); } catch (e) {
  throw new Error('Claude returned non-JSON: ' + raw.slice(0, 200));
}
if (!Array.isArray(ideas)) throw new Error('Expected array');
return ideas.map(i => ({ json: i }));

